//! Cargo-driven `glu32.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x78ee0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff8e000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff8e000000u64)),
        o => panic!("glu32-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:c:cpprt", "engine:pseh", "import:opengl32", "import:gdi32", "import:msvcrt", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "body", "engine:oldnames", "import:kernel32_vista", "engine:chkstk"],
        "x86_64" => &["engine:c:cpprt", "engine:pseh", "import:opengl32", "import:gdi32", "import:msvcrt", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "body", "engine:oldnames", "import:kernel32_vista"],
        "aarch64" => &["engine:c:cpprt", "engine:pseh", "import:opengl32", "import:gdi32", "import:msvcrt", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "body", "engine:oldnames", "import:kernel32_vista", "engine:chkstk"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/opengl/glu32",
        "dll/opengl/glu32",
        "vendor/glu/src/libnurbs/nurbtess",
        "vendor/glu/src/libnurbs/interface",
        "vendor/glu/src/libnurbs/internals",
        "vendor/glu/src/include",
        "vendor/glu/include",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "BUILD_GLU32",
        "LIBRARYBUILD",
        "NDEBUG=",
        "RESOLVE_3D_TEXTURE_SUPPORT",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    Linker::new(target_json)
        .c_from_compile_db("glu32_shims", &["vendor/glu/src/libnurbs/interface/bezierEval.cc", "vendor/glu/src/libnurbs/interface/bezierPatch.cc", "vendor/glu/src/libnurbs/interface/bezierPatchMesh.cc", "vendor/glu/src/libnurbs/interface/glcurveval.cc", "vendor/glu/src/libnurbs/interface/glinterface.cc", "vendor/glu/src/libnurbs/interface/glrenderer.cc", "vendor/glu/src/libnurbs/interface/glsurfeval.cc", "vendor/glu/src/libnurbs/interface/incurveeval.cc", "vendor/glu/src/libnurbs/interface/insurfeval.cc", "vendor/glu/src/libnurbs/internals/arc.cc", "vendor/glu/src/libnurbs/internals/arcsorter.cc", "vendor/glu/src/libnurbs/internals/arctess.cc", "vendor/glu/src/libnurbs/internals/backend.cc", "vendor/glu/src/libnurbs/internals/basiccrveval.cc", "vendor/glu/src/libnurbs/internals/basicsurfeval.cc", "vendor/glu/src/libnurbs/internals/bin.cc", "vendor/glu/src/libnurbs/internals/bufpool.cc", "vendor/glu/src/libnurbs/internals/cachingeval.cc", "vendor/glu/src/libnurbs/internals/ccw.cc", "vendor/glu/src/libnurbs/internals/coveandtiler.cc", "vendor/glu/src/libnurbs/internals/curve.cc", "vendor/glu/src/libnurbs/internals/curvelist.cc", "vendor/glu/src/libnurbs/internals/curvesub.cc", "vendor/glu/src/libnurbs/internals/dataTransform.cc", "vendor/glu/src/libnurbs/internals/displaylist.cc", "vendor/glu/src/libnurbs/internals/flist.cc", "vendor/glu/src/libnurbs/internals/flistsorter.cc", "vendor/glu/src/libnurbs/internals/hull.cc", "vendor/glu/src/libnurbs/internals/intersect.cc", "vendor/glu/src/libnurbs/internals/knotvector.cc", "vendor/glu/src/libnurbs/internals/mapdesc.cc", "vendor/glu/src/libnurbs/internals/mapdescv.cc", "vendor/glu/src/libnurbs/internals/maplist.cc", "vendor/glu/src/libnurbs/internals/mesher.cc", "vendor/glu/src/libnurbs/internals/monoTriangulationBackend.cc", "vendor/glu/src/libnurbs/internals/monotonizer.cc", "vendor/glu/src/libnurbs/internals/mycode.cc", "vendor/glu/src/libnurbs/internals/nurbsinterfac.cc", "vendor/glu/src/libnurbs/internals/nurbstess.cc", "vendor/glu/src/libnurbs/internals/patch.cc", "vendor/glu/src/libnurbs/internals/patchlist.cc", "vendor/glu/src/libnurbs/internals/quilt.cc", "vendor/glu/src/libnurbs/internals/reader.cc", "vendor/glu/src/libnurbs/internals/renderhints.cc", "vendor/glu/src/libnurbs/internals/slicer.cc", "vendor/glu/src/libnurbs/internals/sorter.cc", "vendor/glu/src/libnurbs/internals/splitarcs.cc", "vendor/glu/src/libnurbs/internals/subdivider.cc", "vendor/glu/src/libnurbs/internals/tobezier.cc", "vendor/glu/src/libnurbs/internals/trimline.cc", "vendor/glu/src/libnurbs/internals/trimregion.cc", "vendor/glu/src/libnurbs/internals/trimvertpool.cc", "vendor/glu/src/libnurbs/internals/uarray.cc", "vendor/glu/src/libnurbs/internals/varray.cc", "vendor/glu/src/libnurbs/nurbtess/directedLine.cc", "vendor/glu/src/libnurbs/nurbtess/gridWrap.cc", "vendor/glu/src/libnurbs/nurbtess/monoChain.cc", "vendor/glu/src/libnurbs/nurbtess/monoPolyPart.cc", "vendor/glu/src/libnurbs/nurbtess/monoTriangulation.cc", "vendor/glu/src/libnurbs/nurbtess/partitionX.cc", "vendor/glu/src/libnurbs/nurbtess/partitionY.cc", "vendor/glu/src/libnurbs/nurbtess/polyUtil.cc", "vendor/glu/src/libnurbs/nurbtess/primitiveStream.cc", "vendor/glu/src/libnurbs/nurbtess/quicksort.cc", "vendor/glu/src/libnurbs/nurbtess/rectBlock.cc", "vendor/glu/src/libnurbs/nurbtess/sampleComp.cc", "vendor/glu/src/libnurbs/nurbtess/sampleCompBot.cc", "vendor/glu/src/libnurbs/nurbtess/sampleCompRight.cc", "vendor/glu/src/libnurbs/nurbtess/sampleCompTop.cc", "vendor/glu/src/libnurbs/nurbtess/sampleMonoPoly.cc", "vendor/glu/src/libnurbs/nurbtess/sampledLine.cc", "vendor/glu/src/libnurbs/nurbtess/searchTree.cc", "vendor/glu/src/libnurbs/nurbtess/polyDBG.cc", "vendor/glu/src/libutil/error.c", "vendor/glu/src/libutil/glue.c", "vendor/glu/src/libutil/mipmap.c", "vendor/glu/src/libutil/project.c", "vendor/glu/src/libutil/quad.c", "vendor/glu/src/libutil/registry.c", "vendor/glu/src/libtess/dict.c", "vendor/glu/src/libtess/geom.c", "vendor/glu/src/libtess/memalloc.c", "vendor/glu/src/libtess/mesh.c", "vendor/glu/src/libtess/normal.c", "vendor/glu/src/libtess/priorityq.c", "vendor/glu/src/libtess/render.c", "vendor/glu/src/libtess/sweep.c", "vendor/glu/src/libtess/tess.c", "vendor/glu/src/libtess/tessmono.c"])
        .whole_c_objects("glu32_shims")
        .rc("dll/opengl/glu32/glu32.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/opengl/glu32/glu32.spec", "glu32.dll")
        .import_lib("dll/opengl/opengl32/opengl32.spec", "opengl32.dll", "opengl32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        // No code of its own: link nothing from rustc's bin (its panic
        // handler, i386's rsbegin/rsend), so the PE is cmake's.
        .shell_less()
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
